CREATE TABLE IF NOT EXISTS vazin_native_profiles(id BIGSERIAL PRIMARY KEY,profile_key VARCHAR(190) NOT NULL UNIQUE,label TEXT NOT NULL,site_template_key VARCHAR(190) NOT NULL DEFAULT '',required_connectors_json TEXT NOT NULL DEFAULT '[]',default_extensions_json TEXT NOT NULL DEFAULT '[]',default_settings_json TEXT NOT NULL DEFAULT '{}',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS vazin_managed_sites(id BIGSERIAL PRIMARY KEY,site_id BIGINT NOT NULL UNIQUE REFERENCES cms_sites(id) ON DELETE CASCADE,profile_key VARCHAR(190) NOT NULL,provision_state VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK(provision_state IN('pending','provisioning','ready','degraded','failed','suspended')),panel_ref TEXT NOT NULL DEFAULT '',deployment_ref TEXT NOT NULL DEFAULT '',last_health_json TEXT NOT NULL DEFAULT '{}',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS vazin_native_bindings(site_id BIGINT NOT NULL REFERENCES cms_sites(id) ON DELETE CASCADE,service_key VARCHAR(190) NOT NULL,connector_key VARCHAR(190) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'pending' CHECK(status IN('pending','ready','degraded','disabled','error')),policy_json TEXT NOT NULL DEFAULT '{}',updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(site_id,service_key));
CREATE TABLE IF NOT EXISTS vazin_rollout_events(id BIGSERIAL PRIMARY KEY,site_id BIGINT NOT NULL REFERENCES cms_sites(id) ON DELETE CASCADE,event_key VARCHAR(190) NOT NULL,status VARCHAR(80) NOT NULL,details_json TEXT NOT NULL DEFAULT '{}',created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
